def combinations_colors(colors, n):
    result = []
    for i in range(len(colors)+1):
        for combination in combinations(colors, i):
            result.append(tuple(combination))
    return result

def combinations(colors, n):
    if n == 0:
        return [[]]
    if n == 1:
        return [colors]
    result = []
    for i in range(len(colors)):
        for combination in combinations(colors[i+1:], n-1):
            result.append([colors[i]] + combination)
    return result

