def snake_to_camel(snake_str):
    camel_str = snake_str[0].lower() + snake_str[1:]
    for i in range(len(snake_str)):
        if snake_str[i] == '_':
            camel_str += snake_str[i+1].upper()
            snake_str = snake_str[:i] + snake_str[i+2:]
    return camel_str

