import math
def volume_cylinder(radius, height):
    return math.pi * radius ** 2 * height

def snake_to_camel(snake_str):
    camel_str = snake_str[0].lower() + snake_str[1:]
    for i in range(len(snake_str)):
        if snake_str[i] == '_':
            camel_str += snake_str[i+1].upper()
            snake_str = snake_str[:i] + snake_str[i+2:]
    return camel_str

print(snake_to_camel('python_program'))

def freq_count(lst):
    d = {}
    for i in lst:
        if i in d:
            d[i] += 1
        else:
            d[i] = 1
    return d

def first_Digit(num):
    return num % 10
print(first_Digit(123))

def dif_Square(n):
    for i in range(1,n+1):
        for j in range(1,n+1):
            if i**2 + j**2 == n:
                return True
    return False
print(dif_Square(5))

def smallest_num(list):
    return min(list)

