def sort_matrix(matrix):
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            for k in range(len(matrix[i])):
                if matrix[i][j] > matrix[i][k]:
                    matrix[i][j], matrix[i][k] = matrix[i][k], matrix[i][j]
    return matrix


